<?php if(rt_is_tool($r)): $currentTools=[];foreach(wf_evidence_results(['research_id'=>$r['id']]) as $target){try{rt_read($r['id'],$target['result']['id']);}catch(HttpError){continue;}foreach(json_decode($target['result']['metadata'],true)['evidence']['tool_builds']??[] as $build)$currentTools[]=['result'=>$target['result'],'build'=>$build];}if($currentTools): ?>
<section id="research-tools"><h2>Current research tool builds</h2><p>Download exact source, tests and reproduction instructions. <?=e($r['status']==='Review Complete'?'An independent review is recorded; this is experimental software, not scientific certification.':'Independent review is still required.')?></p><?php foreach($currentTools as $entry): ?><article class="task-brief"><h3><?=e($entry['build']['title'])?></h3><p>Version <?=e($entry['build']['version'])?> · <?=count($entry['build']['tests'])?> recorded tests · <?=e(RT_LICENSE)?></p><div class="actions"><a class="button secondary" href="/research/<?=e($r['slug'])?>/results/<?=e($entry['result']['id'])?>#tool-builds">Read build &amp; tests</a><a class="button secondary" href="/research/<?=e($r['slug'])?>/results/<?=e($entry['result']['id'])?>/tools/<?=e($entry['build']['id'])?>/bundle.json">Download tool bundle</a></div></article><?php endforeach ?></section>
<?php endif;endif ?>